<?php
require_once __DIR__.'/_bootstrap.php'; require_once __DIR__.'/_layout.php';
$session=sc_require_session();$error=null;try{$mailbox=$sc_repository->mailbox($session);$messages=$mailbox?$sc_repository->voicemail_messages($session):[];}catch(Throwable $exception){$mailbox=null;$messages=[];$error='Visual Voicemail is unavailable on this FusionPBX installation.';}
sc_render_header($session,'voicemail','Voicemail');
?>
<?php if($error){?><div class="sc-alert error"><?=sc_escape($error)?></div><?php }elseif(!$mailbox){?><div class="sc-card sc-empty"><h2>No mailbox</h2><p>No enabled FusionPBX mailbox is assigned to this extension.</p></div><?php }elseif(!$messages){?><div class="sc-card sc-empty"><h2>No messages</h2><p>New voicemail messages will appear here.</p></div><?php }else{?><div class="sc-grid"><?php foreach($messages as $message){$read=($message['message_status']??'')==='saved'||(int)($message['read_epoch']??0)>0;$message_uuid=(string)$message['voicemail_message_uuid'];$handle=$sc_repository->voicemail_message_handle($session,$message_uuid);$playback_token=$sc_repository->voicemail_playback_token($session,$message_uuid);$download_token=$sc_repository->voicemail_download_token($session,$message_uuid);$epoch=(int)$message['created_epoch'];?><article class="sc-card sc-message <?=$read?'':'unread'?>" data-voicemail-message data-read="<?=$read?'true':'false'?>"><div class="sc-message-head"><div><strong><?=sc_escape($message['caller_id_name']?:$message['caller_id_number']?:'Unknown caller')?></strong><div class="sc-muted"><time datetime="<?=sc_escape(gmdate('c',$epoch))?>" data-epoch="<?=$epoch?>"><?=sc_escape(gmdate('M j, Y · g:i A',$epoch))?></time> · <?=sc_escape(gmdate('i:s',(int)($message['message_length']??0)))?></div></div><span class="sc-badge"><?=$read?'Read':'New'?></span></div><audio controls preload="none" src="media.php?token=<?=rawurlencode($playback_token)?>"></audio><?php if(!empty($message['message_transcription'])){?><div class="sc-transcript"><?=nl2br(sc_escape($message['message_transcription']))?></div><?php }?><div class="sc-actions"><a class="sc-button secondary" href="media.php?token=<?=rawurlencode($download_token)?>" download>Download</a><form method="post" action="action.php" data-read-form><input type="hidden" name="csrf" value="<?=sc_escape($session['csrf'])?>"><input type="hidden" name="action" value="message_read"><input type="hidden" name="id" value="<?=sc_escape($handle)?>"><input type="hidden" name="read" value="<?=$read?'false':'true'?>"><button class="sc-button secondary" type="submit">Mark <?=$read?'unread':'read'?></button></form><a class="sc-button danger" href="confirm-delete.php?id=<?=rawurlencode($handle)?>">Delete</a></div></article><?php }?></div><?php }?>
<?php sc_render_footer(); ?>
